static PyObject *crc64nvme(
    PyObject *Py_UNUSED(module),
    PyObject *args,
    PyObject *kwargs
) {
    Py_buffer view;
    uint64_t previous = 0;
    PyObject *previous_object = NULL;

    static char *keywords[] = {
        "data",
        "previous",
        NULL,
    };

    if (!PyArg_ParseTupleAndKeywords(
            args,
            kwargs,
            "y*|O:crc64nvme",
            keywords,
            &view,
            &previous_object
        )) {
        return NULL;
    }

    if (previous_object != NULL) {
        previous = (uint64_t)PyLong_AsUnsignedLongLong(previous_object);
        if (PyErr_Occurred()) {
            PyBuffer_Release(&view);
            return NULL;
        }
    }

    uint64_t crc = previous ^ CRC64_MASK;
    const unsigned char *data = (const unsigned char *)view.buf;
    Py_ssize_t length = view.len;

    Py_BEGIN_ALLOW_THREADS;

    for (Py_ssize_t i = 0; i < length; i++) {
        crc = table[(crc ^ data[i]) & 0xff] ^ (crc >> 8);
    }

    Py_END_ALLOW_THREADS;

    PyBuffer_Release(&view);

    return PyLong_FromUnsignedLongLong(crc ^ CRC64_MASK);
}

